const { runId, text } = msg.payload || {};
if (typeof runId !== 'string' || !runId || typeof text !== 'string' || !text.trim()) { msg.statusCode = 400; msg.payload = { error: 'Invalid request' }; return [null, null, msg]; }
const base = { runId, text, agentObservation: { runId } };
const writer = { ...base, topic: 'writer', payload: `In one sentence, draft a release note about ${text}. Reply only with the sentence.` };
const reviewer = { ...base, topic: 'reviewer', payload: `In one sentence, suggest a test for ${text}. Reply only with the sentence.` };
msg.statusCode = 202; msg.payload = { accepted: true };
return [writer, reviewer, msg];

if (msg.agentExecution?.status !== 'completed' || typeof msg.payload !== 'string' || !msg.payload.trim()) return [null, null, msg];
if (msg.topic === 'summary') return [null, msg, null];
msg.parts = { id: msg.runId, index: msg.topic === 'writer' ? 0 : 1, count: 2 };
return [msg, null, null];

if (!Array.isArray(msg.payload) || msg.payload.length !== 2 || msg.payload.some(value => typeof value !== 'string' || !value.trim())) return [null, msg];
msg.payload = `In one sentence, summarize the release note and test suggestion:
${msg.payload[0]}
${msg.payload[1]}`;
msg.topic = 'summary'; msg.agentObservation = { runId: msg.runId }; delete msg.parts; delete msg.sessionID;
return [msg, null];

if (msg.agentExecution?.status !== 'completed' || typeof msg.payload !== 'string' || !msg.payload.trim()) return [null, msg];
msg.payload = { runId: msg.runId, eventId: `${msg.runId}:completed`, status: 'completed', output: msg.payload };
return [msg, null];
